script:
.navari-fit-phrase {
  display: inline-block;
  color: var(--navari-orange);
  letter-spacing: 0.12em;
  transform: translateX(-0.16em);
  transition: letter-spacing 900ms cubic-bezier(0.22, 1, 0.36, 1), transform 900ms cubic-bezier(0.22, 1, 0.36, 1), color 500ms ease;
}
.navari-fit-phrase.navari-fit-aligned {
  letter-spacing: -0.055em;
  transform: translateX(0);
  color: #FFFFFF;
}
.navari-about-network svg path { stroke-dasharray: 1; stroke-dashoffset: 0; }
.navari-about-network.navari-network-live svg path { animation: navari-network-draw 1100ms cubic-bezier(0.22, 1, 0.36, 1) both; }
@keyframes navari-network-draw { from { stroke-dasharray: 340; stroke-dashoffset: 340; } to { stroke-dasharray: 340; stroke-dashoffset: 0; } }
.navari-process { position: relative; }
.navari-process-step { transition: background-color 220ms ease, padding-top 220ms ease; }
.navari-process-step.navari-step-active { background-color: rgba(16,152,232,0.045); }
.navari-module.navari-module-active { background-color: var(--navari-ink) !important; color: #FFFFFF !important; transform: scale(1.035); }
.navari-industry-row { cursor: default; }
@media (prefers-reduced-motion: reduce) {
  .navari-fit-phrase, .navari-fit-phrase.navari-fit-aligned, .navari-process-step, .navari-module { transition: none; transform: none; }
  .navari-about-network.navari-network-live svg path { animation: none; }
}
@media (max-width: 767px) { .navari-fit-phrase { letter-spacing: -0.04em; transform: none; } }

(() => { const init = () => {
(() => {
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const fit = document.querySelector('.navari-fit-phrase');
  const network = document.querySelector('.navari-about-network');
  const process = document.querySelector('.navari-process');
  if (!reduce && 'IntersectionObserver' in window) {
    if (fit) {
      const fitObserver = new IntersectionObserver((entries) => entries.forEach((entry) => {
        if (entry.isIntersecting) { fit.classList.add('navari-fit-aligned'); fitObserver.unobserve(entry.target); }
      }), { threshold: 0.55 });
      fitObserver.observe(fit);
    }
    if (network) {
      const networkObserver = new IntersectionObserver((entries) => entries.forEach((entry) => {
        if (entry.isIntersecting) { network.classList.add('navari-network-live'); networkObserver.unobserve(entry.target); }
      }), { threshold: 0.3 });
      networkObserver.observe(network);
    }
    if (process) {
      const steps = process.querySelectorAll('.navari-process-step');
      const processObserver = new IntersectionObserver((entries) => entries.forEach((entry) => {
        if (entry.isIntersecting) {
          const index = Array.prototype.indexOf.call(steps, entry.target);
          steps.forEach((step, i) => step.classList.toggle('navari-step-active', i <= index));
        }
      }), { threshold: 0.55 });
      steps.forEach((step) => processObserver.observe(step));
    }
  } else if (fit) { fit.classList.add('navari-fit-aligned'); }
  document.querySelectorAll('.navari-module').forEach((module) => {
    const activate = () => {
      document.querySelectorAll('.navari-module').forEach((item) => item.classList.remove('navari-module-active'));
      module.classList.add('navari-module-active');
    };
    module.addEventListener('mouseenter', activate);
    module.addEventListener('focus', activate);
    module.addEventListener('click', activate);
  });
})();
}; if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true}); else init(); })();

.navari-hero-eyebrow {
    position: relative;
    display: inline-flex;
    align-items: baseline;
    padding-bottom: 10px;
    cursor: default;
}

.navari-hero-eyebrow::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: 0;
    width: 0;
    height: 2px;
    background: var(--navari-ocean);
    transition: width 500ms cubic-bezier(0.22, 1, 0.36, 1);
}

.navari-hero-eyebrow:hover::after {
    width: 100%;
}

.navari-eyebrow-clear {
    display: inline-block;
    font-weight: 700;
    transition: letter-spacing 300ms cubic-bezier(0.22, 1, 0.36, 1), transform 300ms cubic-bezier(0.22, 1, 0.36, 1);
}

.navari-hero-eyebrow:hover .navari-eyebrow-clear {
    letter-spacing: 0.02em;
    transform: translateY(-1px);
}

/* Wordplay: the word "clear" literally sharpens into focus as it reveals,
   like a lens settling - a small visual pun on "made clear". */
.navari-eyebrow-clear {
    filter: blur(6px);
    opacity: 0.35;
}

.navari-reveal.navari-visible .navari-eyebrow-clear {
    animation: navari-clear-focus 900ms 280ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@keyframes navari-clear-focus {
    from {
        filter: blur(6px);
        opacity: 0.35;
    }
    to {
        filter: blur(0);
        opacity: 1;
    }
}

@media (prefers-reduced-motion: reduce) {
    .navari-hero-eyebrow::after,
    .navari-eyebrow-clear {
        transition: none;
    }
    .navari-eyebrow-clear {
        filter: none;
        opacity: 1;
        animation: none;
    }
}

.navari-word-settle .navari-settle-word {
    display: inline-block;
    opacity: 0;
    transform: translateY(14px) scale(0.98);
    transition: opacity 620ms cubic-bezier(0.22, 1, 0.36, 1), transform 620ms cubic-bezier(0.22, 1, 0.36, 1);
}
.navari-word-settle .navari-settle-word:nth-child(1) { transition-delay: 0ms; }
.navari-word-settle .navari-settle-word:nth-child(2) { transition-delay: 70ms; }
.navari-word-settle .navari-settle-word:nth-child(3) { transition-delay: 140ms; }
.navari-word-settle .navari-settle-word:nth-child(4) { transition-delay: 210ms; }
.navari-word-settle .navari-settle-word:nth-child(5) { transition-delay: 280ms; }

.navari-reveal.navari-visible.navari-word-settle .navari-settle-word {
    opacity: 1;
    transform: translateY(0) scale(1);
}

@media (prefers-reduced-motion: reduce) {
    .navari-word-settle .navari-settle-word {
        opacity: 1;
        transform: none;
        transition: none;
    }
}

.navari-eco-pill { transition: border-color 180ms ease, background-color 180ms ease, transform 180ms ease, box-shadow 180ms ease; }
.navari-eco-pill:hover, .navari-eco-pill:focus, .navari-eco-pill.navari-eco-open { background-color: #FFFFFF; border-color: var(--navari-red); box-shadow: 0 10px 24px rgba(21,25,29,0.08); outline: none; transform: translateY(-2px); }
.navari-eco-pill:hover .navari-eco-desc, .navari-eco-pill:focus .navari-eco-desc, .navari-eco-pill.navari-eco-open .navari-eco-desc { opacity: 1; transform: translate(-50%, 0); visibility: visible; }
.navari-eco-pill:focus-visible { box-shadow: 0 0 0 3px rgba(202,50,49,0.28), 0 10px 24px rgba(21,25,29,0.08); }
@media (max-width: 767px) { .navari-eco-pill .navari-eco-desc { bottom: auto; left: 0; right: auto; top: calc(100% + 8px); transform: translate(0, -6px); width: min(250px, calc(100vw - 40px)); } .navari-eco-pill.navari-eco-open .navari-eco-desc, .navari-eco-pill:focus .navari-eco-desc { transform: translate(0, 0); } }
@media (prefers-reduced-motion: reduce) { .navari-eco-pill, .navari-eco-desc { transition: none; } .navari-eco-pill:hover, .navari-eco-pill:focus, .navari-eco-pill.navari-eco-open { transform: none; } }

(() => { const init = () => {
(() => {
  const pills = Array.from(document.querySelectorAll('.navari-eco-pill'));
  const closeAll = (except) => pills.forEach((pill) => {
    if (pill !== except) {
      pill.classList.remove('navari-eco-open');
      pill.setAttribute('aria-expanded', 'false');
    }
  });

  pills.forEach((pill) => {
    const toggle = () => {
      const opening = !pill.classList.contains('navari-eco-open');
      closeAll(pill);
      pill.classList.toggle('navari-eco-open', opening);
      pill.setAttribute('aria-expanded', String(opening));
    };

    pill.addEventListener('click', toggle);
    pill.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        toggle();
      }
      if (event.key === 'Escape') {
        pill.classList.remove('navari-eco-open');
        pill.setAttribute('aria-expanded', 'false');
        pill.blur();
      }
    });
  });

  document.addEventListener('click', (event) => {
    if (!event.target.closest('.navari-eco-pill')) closeAll();
  });
})();
}; if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true}); else init(); })();

(() => { const init = () => {
(() => {
  const mobileProducts = document.querySelector('.navari-mobile-products-dropdown');
  const mobileProductsMenu = document.querySelector('.navari-mobile-products-dropdown-menu');

  if (mobileProducts && mobileProductsMenu) {
    mobileProducts.setAttribute('role', 'button');
    mobileProducts.setAttribute('aria-expanded', 'false');

    const toggle = () => {
      const isOpen = mobileProducts.getAttribute('aria-expanded') === 'true';
      mobileProductsMenu.style.display = isOpen ? 'none' : 'flex';
      mobileProducts.setAttribute('aria-expanded', String(!isOpen));
    };

    mobileProducts.addEventListener('click', (event) => {
      if (event.target.closest('.navari-mobile-products-dropdown-menu a')) {
        return;
      }
      toggle();
    });

    mobileProducts.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        toggle();
      }
    });
  }
})();

}; if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true}); else init(); })();

(() => { const init = () => {
(() => {
    const path = window.location.pathname.replace(/\/+$/, '') || '/';

    const routeMap = {
        '/': '.navari-home-link',
        '/home': '.navari-home-link',
        '/about': '.navari-about-link',
        '/services': '.navari-services-link',
        '/stories': '.navari-stories-link',
        '/contacts': '.navari-contact-link'
    };

    document.querySelectorAll(
        '.navari-home-link, .navari-about-link, .navari-services-link, .navari-stories-link, .navari-contact-link'
    ).forEach((link) => {
        link.classList.remove('navari-nav-link-active');
        link.removeAttribute('aria-current');
    });

    const activeSelector = routeMap[path];

    if (activeSelector) {
        document.querySelectorAll(activeSelector).forEach((link) => {
            link.classList.add('navari-nav-link-active');
            link.setAttribute('aria-current', 'page');
        });
    }
})();

}; if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true}); else init(); })();

.navari-location-pulse {
    position: relative;
}
.navari-location-pulse::after {
    content: "";
    position: absolute;
    inset: -6px;
    border-radius: 100px;
    border: 1px solid var(--navari-red);
    opacity: 0.6;
    animation: navari-pulse-ring 2200ms ease-out infinite;
}
@keyframes navari-pulse-ring {
    0% { transform: scale(0.6); opacity: 0.6; }
    100% { transform: scale(2.4); opacity: 0; }
}
@media (prefers-reduced-motion: reduce) {
    .navari-location-pulse::after {
        animation: none;
        display: none;
    }
}

(() => { const init = () => {
(() => {
const toggle = document.querySelector('.navari-mobile-menu-toggle');
const drawer = document.querySelector('.navari-mobile-drawer');

if (toggle && drawer) {
  const closeDrawer = () => {
    drawer.style.display = 'none';
    drawer.setAttribute('hidden', 'hidden');
    toggle.setAttribute('aria-expanded', 'false');
    toggle.setAttribute('aria-label', 'Open navigation');
  };

  toggle.addEventListener('click', (event) => {
    event.stopPropagation();

    const isOpen = toggle.getAttribute('aria-expanded') === 'true';

    if (isOpen) {
      closeDrawer();
    } else {
      drawer.style.display = 'block';
      drawer.removeAttribute('hidden');
      toggle.setAttribute('aria-expanded', 'true');
      toggle.setAttribute('aria-label', 'Close navigation');
    }
  });

  drawer.querySelectorAll('a').forEach((link) => {
    link.addEventListener('click', closeDrawer);
  });

  document.addEventListener('click', (event) => {
    if (
      toggle.getAttribute('aria-expanded') === 'true' &&
      !drawer.contains(event.target) &&
      !toggle.contains(event.target)
    ) {
      closeDrawer();
    }
  });
}

if(toggle && drawer) {
 document.addEventListener('keydown', e => { if(e.key === 'Escape' && toggle.getAttribute('aria-expanded') === 'true') { toggle.click(); toggle.focus(); } });
 window.matchMedia('(min-width:1025px)').addEventListener('change', e => {if(e.matches && toggle.getAttribute('aria-expanded') === 'true') toggle.click();});
}
})();
}; if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true}); else init(); })();

(() => { const init = () => {
const products = document.querySelector('.navari-products-trigger');
const menu = document.querySelector('.navari-products-dropdown');

if (products && menu) {
  const openMenu = () => {
    menu.style.opacity = '1';
    menu.style.visibility = 'visible';
    menu.style.pointerEvents = 'auto';
    products.setAttribute('aria-expanded', 'true');
  };

  const closeMenu = (focusTrigger) => {
    menu.style.opacity = '0';
    menu.style.visibility = 'hidden';
    menu.style.pointerEvents = 'none';
    products.setAttribute('aria-expanded', 'false');
    if (focusTrigger) products.focus();
  };

  products.addEventListener('click', (event) => {
    if (event.target.closest('.navari-products-dropdown a')) return;

    const isOpen = products.getAttribute('aria-expanded') === 'true';

    if (isOpen) {
      closeMenu(false);
    } else {
      openMenu();
    }
  });

  products.addEventListener('keydown', (event) => {
    if (event.target !== products) return;
    const isOpen = products.getAttribute('aria-expanded') === 'true';

    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      if (isOpen) {
        closeMenu(false);
      } else {
        openMenu();
        const firstLink = menu.querySelector('a');
        if (firstLink) firstLink.focus();
      }
    } else if (event.key === 'Escape' && isOpen) {
      closeMenu(true);
    } else if (event.key === 'ArrowDown' && !isOpen) {
      event.preventDefault();
      openMenu();
      const firstLink = menu.querySelector('a');
      if (firstLink) firstLink.focus();
    }
  });

  menu.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') {
      closeMenu(true);
    }
  });

  document.addEventListener('click', (event) => {
    if (!products.contains(event.target) && !menu.contains(event.target)) {
      closeMenu(false);
    }
  });

  document.addEventListener('focusin', (event) => {
    if (!products.contains(event.target) && !menu.contains(event.target)) {
      closeMenu(false);
    }
  });
}

}; if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true}); else init(); })();

.navari-reveal { opacity: 0; transform: translateY(16px); transition: opacity 520ms ease, transform 520ms ease; }
.navari-reveal.navari-visible { opacity: 1; transform: translateY(0); }
.navari-card { transition: transform 220ms ease, box-shadow 220ms ease; }
.navari-card:hover { transform: translateY(-3px); box-shadow: 0 20px 46px rgba(21,25,29,0.10); }
@media (prefers-reduced-motion: reduce) { .navari-reveal, .navari-card { opacity: 1; transform: none; transition: none; } }
@media (max-width: 767px) { .navari-card { border-radius: 20px !important; } }

(() => { const init = () => {
const targets = document.querySelectorAll('.navari-reveal');
if ('IntersectionObserver' in window) {
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add('navari-visible');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.12 });
  targets.forEach((target) => observer.observe(target));
} else {
  targets.forEach((target) => target.classList.add('navari-visible'));
}
}; if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true}); else init(); })();

(() => {
  const init = () => {
    const form = document.querySelector('.navari-contact-form');
    if (!form) return;
    form.removeAttribute('novalidate');
    const button = form.querySelector('[type="submit"], button');
    const success = document.querySelector('.navari-form-success');
    const failure = document.querySelector('.navari-form-error');
    let busy = false;
    form.addEventListener('submit', async event => {
      event.preventDefault();
      if (busy || !form.reportValidity()) return;
      const values = new FormData(form);
      const data = Object.fromEntries(['email', 'company', 'phone', 'help_type', 'message'].map(key => [key, String(values.get(key) || '').trim()]));
      data.name_field = String(values.get('name') || '').trim();
      if (!data.name_field || !data.message) { form.querySelector(!data.name_field ? '[name="name"]' : '[name="message"]').focus(); return; }
      busy = true;
      const label = button.textContent;
      button.disabled = true;
      button.textContent = 'Sending…';
      form.setAttribute('aria-busy', 'true');
      if (success) success.style.display = 'none';
      if (failure) failure.style.display = 'none';
      try {
        const headers = {'Content-Type': 'application/json'};
        if (window.frappe?.csrf_token) headers['X-Frappe-CSRF-Token'] = window.frappe.csrf_token;
        const response = await fetch('/api/method/frappe.website.doctype.web_form.web_form.accept', {
          method: 'POST', headers,
          body: JSON.stringify({web_form: 'navari-contact-submission', data})
        });
        if (!response.ok) throw new Error('Submission failed');
        const result = await response.json();
        if (result.exc || result.exception) throw new Error('Submission rejected');
        form.reset();
        if (success) success.style.display = 'block';
      } catch {
        if (failure) failure.style.display = 'block';
      } finally {
        busy = false;
        button.disabled = false;
        button.textContent = label;
        form.removeAttribute('aria-busy');
      }
    });
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once: true});
  else init();
})();

(() => { const init = () => {
(() => {
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const network = document.querySelector('.navari-services-network');
  const friction = document.querySelector('.navari-friction-word');
  if (!reduce && 'IntersectionObserver' in window) {
    [[network, 'navari-network-live', 0.25], [friction, 'navari-friction-settled', 0.45]].forEach(([node, className, threshold]) => {
      if (!node) return;
      const observer = new IntersectionObserver((entries) => entries.forEach((entry) => {
        if (entry.isIntersecting) { node.classList.add(className); observer.unobserve(node); }
      }), { threshold });
      observer.observe(node);
    });
  } else {
    if (network) network.classList.add('navari-network-live');
    if (friction) friction.classList.add('navari-friction-settled');
  }
  const detail = document.querySelector('.navari-ecosystem-detail');
  document.querySelectorAll('.navari-ecosystem-node').forEach((node) => {
    const activate = () => {
      document.querySelectorAll('.navari-ecosystem-node').forEach((item) => item.classList.remove('navari-ecosystem-active'));
      node.classList.add('navari-ecosystem-active');
      if (detail) detail.textContent = node.getAttribute('aria-label') || '';
    };
    node.addEventListener('mouseenter', activate);
    node.addEventListener('focus', activate);
    node.addEventListener('click', activate);
  });
})();
}; if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true}); else init(); })();

