.navari-services-network.navari-network-live .navari-network-path { animation: navari-services-draw 900ms cubic-bezier(0.22, 1, 0.36, 1) forwards; }
.navari-services-network.navari-network-live .navari-network-path:nth-child(2) { animation-delay: 90ms; }
.navari-services-network.navari-network-live .navari-network-path:nth-child(3) { animation-delay: 180ms; }
.navari-services-network.navari-network-live .navari-network-path:nth-child(4) { animation-delay: 270ms; }
.navari-services-network.navari-network-live .navari-network-path:nth-child(5) { animation-delay: 360ms; }
.navari-services-network.navari-network-live .navari-network-path:nth-child(6) { animation-delay: 450ms; }
@keyframes navari-services-draw { to { stroke-dashoffset: 0; } }
.navari-friction-word { letter-spacing: 0.07em !important; transform: translateX(-0.05em); transition: letter-spacing 850ms cubic-bezier(0.22, 1, 0.36, 1), transform 850ms cubic-bezier(0.22, 1, 0.36, 1); }
