@media (prefers-reduced-motion: reduce) { .navari-services-network .navari-network-path { stroke-dasharray: none; stroke-dashoffset: 0; animation: none !important; } .navari-friction-word, .navari-friction-word.navari-friction-settled, .navari-ecosystem-node { transform: none; transition: none !important; } }
