(() => { const init = () => {
(() => {
  const lists = Array.from(document.querySelectorAll('[data-story-page]'));
  const buttons = Array.from(document.querySelectorAll('[data-page]'));
  if (!lists.length || !buttons.length) return;

  const showPage = (page) => {
    lists.forEach((list) => {
      const active = list.getAttribute('data-story-page') === page;
      list.style.display = active ? 'flex' : 'none';
      list.setAttribute('aria-hidden', String(!active));
    });
    buttons.forEach((button) => {
      const active = button.getAttribute('data-page') === page;
      if (active) {
        button.setAttribute('aria-current', 'page');
        button.style.backgroundColor = 'var(--navari-ink)';
        button.style.borderColor = 'var(--navari-ink)';
        button.style.color = 'var(--navari-paper)';
      } else {
        button.removeAttribute('aria-current');
        button.style.backgroundColor = 'transparent';
        button.style.borderColor = 'rgba(21,25,29,0.20)';
        button.style.color = 'var(--navari-ink)';
      }
    });
  };

  buttons.forEach((button) => button.addEventListener('click', () => {
    showPage(button.getAttribute('data-page'));
    const heading = document.querySelector('#stories-list');
    if (heading) heading.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' });
  }));

  showPage('1');
})();
}; if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once:true}); else init(); })();
